__device__ float3 sample(int x,int y){
    unsigned int texel=rgbe[max(0,min(31,y))][x&63];
    float scale=ldexpf(1.f,(int)(texel>>24)-136);
    return fw::v3((float)(texel&255),(float)((texel>>8)&255),(float)((texel>>16)&255))*scale;
}
__device__ float3 radiance(float3 direction){
    float u=fw::fract(atan2f(direction.z,direction.x)*.159154943f+.72f)*64.f-.5f;
    float v=acosf(fw::clamp(direction.y,-1.f,1.f))*.318309886f*32.f-.5f;
    int x=(int)floorf(u),y=(int)floorf(v);
    float3 a=fw::mix(sample(x,y),sample(x+1,y),u-x);
    float3 b=fw::mix(sample(x,y+1),sample(x+1,y+1),u-x);
    return fw::mix(a,b,v-y);
}
